import { test, expect } from '@playwright/test';

test.describe('Modal with Tabbed Content - Active Tab Persistence', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-tabbed-content');
  });

  test('should remember and display the active tab when reopening the modal', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify first tab is active
    const firstTab = page.getByRole('tab', { name: /tab 1/i });
    await expect(firstTab).toBeVisible();

    // Verify content of first tab is displayed
    const firstTabContent = page.getByRole('region', { name: /tab 1 content/i });
    await expect(firstTabContent).toBeVisible();

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Reopen the modal
    await openButton.click();

    // Verify modal is visible again
    await expect(modal).toBeVisible();

    // Verify first tab is still active
    await expect(firstTab).toBeVisible();

    // Verify content of first tab is still displayed
    await expect(firstTabContent).toBeVisible();
  });

  test('should remember and display the active tab when switching between tabs', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify first tab is active
    const firstTab = page.getByRole('tab', { name: /tab 1/i });
    await expect(firstTab).toBeVisible();

    // Verify content of first tab is displayed
    const firstTabContent = page.getByRole('region', { name: /tab 1 content/i });
    await expect(firstTabContent).toBeVisible();

    // Switch to second tab
    const secondTab = page.getByRole('tab', { name: /tab 2/i });
    await secondTab.click();

    // Verify second tab is now active
    await expect(secondTab).toBeVisible();

    // Verify content of second tab is displayed
    const secondTabContent = page.getByRole('region', { name: /tab 2 content/i });
    await expect(secondTabContent).toBeVisible();

    // Switch back to first tab
    await firstTab.click();

    // Verify first tab is active again
    await expect(firstTab).toBeVisible();

    // Verify content of first tab is still displayed
    await expect(firstTabContent).toBeVisible();

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Reopen the modal
    await openButton.click();

    // Verify modal is visible again
    await expect(modal).toBeVisible();

    // Verify first tab is active
    await expect(firstTab).toBeVisible();

    // Verify content of first tab is still displayed
    await expect(firstTabContent).toBeVisible();
  });
});
